{"content":""""Provider notification adapter for the billing service."""

import hashlib
import hmac
import json

from payhook.errors import InvalidNotification

_TIMESTAMP_HEADER = "X-Pay-Timestamp"
_SIGNATURE_HEADER = "X-Pay-Signature"
_SIGNATURE_PREFIX = "v1="
_SIGNATURE_HEX_LENGTH = 64  # SHA-256 hex digest length.
_TIMESTAMP_TOLERANCE_SECONDS = 300
_HEX_DIGITS = frozenset("0123456789abcdefABCDEF")
_CURRENCY_LETTERS = frozenset("ABCDEFGHIJKLMNOPQRSTUVWXYZ")


def _header(headers, name):
    """Return the value for ``name`` from ``headers``, or ``None``.

    Lookups fall back to a case-insensitive scan so that header maps with
    non-canonical casing are still accepted.
    """
    if headers is None:
        return None
    try:
        value = headers.get(name)
    except AttributeError:
        return None
    if value is not None:
        return value
    try:
        items = headers.items()
    except AttributeError:
        return None
    for key, candidate in items:
        if isinstance(key, str) and key.lower() == name.lower():
            return candidate
    return None


def _is_decimal_integer(text):
    """Return True if ``text`` is a plain decimal (optionally signed) integer."""
    if not text:
        return False
    digits = text[1:] if text[0] in "+-" else text
    return digits.isdigit()


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format.

    ``raw_body`` and ``headers`` are exactly what the public ingress received;
    ``secret`` is the configured signing key and ``now`` the current service
    time (Unix seconds). Raises :class:`InvalidNotification` for anything that
    cannot be accepted; otherwise returns a new dictionary with the
    ``event_id``, ``account_id``, ``amount_minor`` and ``currency`` fields.
    """
    if not isinstance(raw_body, (bytes, bytearray, memoryview)):
        raise InvalidNotification("raw body must be bytes")
    body_bytes = bytes(raw_body)

    timestamp = _header(headers, _TIMESTAMP_HEADER)
    signature = _header(headers, _SIGNATURE_HEADER)

    # Header sanity checks (cheap, not secret dependent).
    if not isinstance(timestamp, str) or not _is_decimal_integer(timestamp):
        raise InvalidNotification("missing or malformed X-Pay-Timestamp")
    if not isinstance(signature, str) or not signature.startswith(_SIGNATURE_PREFIX):
        raise InvalidNotification("missing or malformed X-Pay-Signature")
    provided_hex = signature[len(_SIGNATURE_PREFIX):]
    if len(provided_hex) != _SIGNATURE_HEX_LENGTH or not all(
        c in _HEX_DIGITS for c in provided_hex
    ):
        raise InvalidNotification("malformed X-Pay-Signature digest")

    # The digest covers the exact ASCII timestamp, a "." byte, and the exact
    # received body bytes, in that order. hmac.compare_digest keeps the
    # comparison from leaking secret-dependent timing information.
    if isinstance(secret, str):
        secret = secret.encode("utf-8")
    signed_payload = timestamp.encode("ascii") + b"." + body_bytes
    expected_hex = hmac.new(secret, signed_payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected_hex, provided_hex.lower()):
        raise InvalidNotification("signature does not match body")

    # Anti-replay: accept only deliveries within the tolerance window.
    delivery_time = int(timestamp)
    if abs(now - delivery_time) > _TIMESTAMP_TOLERANCE_SECONDS:
        raise InvalidNotification("timestamp outside the acceptance window")

    # Body: UTF-8 JSON object with the required fields.
    try:
        event = json.loads(body_bytes)
    except ValueError:  # includes JSONDecodeError and UnicodeDecodeError
        raise InvalidNotification("body is not valid UTF-8 JSON") from None
    if not isinstance(event, dict):
        raise InvalidNotification("body is not a JSON object")

    event_id = event.get("event_id")
    account_id = event.get("account_id")
    amount_minor = event.get("amount_minor")
    currency = event.get("currency")

    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("event_id must be a nonempty string")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("account_id must be a nonempty string")
    if isinstance(amount_minor, bool) or not isinstance(amount_minor, int):
        raise InvalidNotification("amount_minor must be an integer")
    if amount_minor < 0:
        raise InvalidNotification("amount_minor must be nonnegative")
    if not isinstance(currency, str) or len(currency) != 3 or not all(
        c in _CURRENCY_LETTERS for c in currency
    ):
        raise InvalidNotification("currency must be three uppercase ASCII letters")

    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }
